parameters.command:
python3 - << 'PYEOF'
import json

# Load the full IxP node definition
ixp_def = json.load(open('/tmp/ixp_full_node.json'))
end_def_data = json.load(open('/tmp/end_node.json'))
end_def = end_def_data['Data']['Node']

# Input defaults from registry
inputDefaults = ixp_def['inputDefaults']
model_blob = inputDefaults['model']
# modelName is null — use modelDisplayName per Authoring Rule #1
model_blob_copy = dict(model_blob)
if not model_blob_copy.get('modelName'):
    model_blob_copy['modelName'] = model_blob_copy['modelDisplayName']

# Output definitions
output_def = ixp_def['outputDefinition']['output']
error_def = ixp_def['outputDefinition']['error']

IXP_NODE_TYPE = ixp_def['nodeType']
IXP_VERSION = ixp_def['version']  # "1.0.0"

flow = {
    "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
    "version": "1.8",
    "name": "FormsClassify",
    "variables": {
        "globals": [
            {
                "name": "pdfDocument",
                "type": "string",
                "scope": "in",
                "description": "File reference of the incoming PDF form to classify and extract"
            },
            {
                "name": "extractionResult",
                "type": "object",
                "scope": "out",
                "description": "Extracted fields from the classified PDF form"
            }
        ],
        "nodes": []
    },
    "nodes": [
        {
            "id": "start",
            "type": "core.trigger.manual",
            "typeVersion": "1.0",
            "display": {"label": "Receive PDF Form"},
            "inputs": {
                "entryPointId": "dd959b32-e0d5-4a04-be9c-3ab99370aeb4",
                "isDefaultEntryPoint": True
            }
        },
        {
            "id": "classifyAndExtract",
            "type": IXP_NODE_TYPE,
            "typeVersion": IXP_VERSION,
            "display": {"label": "Classify and Extract Form Fields"},
            "inputs": {
                "model": model_blob_copy,
                "modelName": inputDefaults['modelName'],
                "description": inputDefaults.get('description', ''),
                "projectName": inputDefaults['projectName'],
                "versionTag": "",
                "folderKey": inputDefaults['folderKey'],
                "folderName": inputDefaults['folderName'],
                "fileRef": "=js:$vars.start.output.pdfDocument",
                "pageRange": ""
            },
            "outputs": {
                "output": output_def,
                "error": error_def
            }
        },
        {
            "id": "end",
            "type": "core.control.end",
            "typeVersion": "1.0",
            "display": {"label": "End"},
            "inputs": {},
            "outputs": {
                "extractionResult": {
                    "source": "=js:$vars.classifyAndExtract.output"
                }
            }
        }
    ],
    "edges": [
        {
            "id": "edge-start-to-ixp",
            "source": "start",
            "target": "classifyAndExtract",
            "sourcePort": "output",
            "targetPort": "input"
        },
        {
            "id": "edge-ixp-to-end",
            "source": "classifyAndExtract",
            "target": "end",
            "sourcePort": "success",
            "targetPort": "input"
        }
    ],
    "definitions": [
        # manual trigger definition (from existing scaffolded flow)
        {
            "nodeType": "core.trigger.manual",
            "version": "1.0",
            "category": "trigger",
            "description": "Start workflow manually",
            "tags": ["trigger", "start", "manual"],
            "sortOrder": 40,
            "display": {"label": "Manual trigger", "icon": "play", "shape": "circle"},
            "handleConfiguration": [
                {
                    "position": "right",
                    "handles": [
                        {
                            "id": "output",
                            "type": "source",
                            "handleType": "output",
                            "showButton": True,
                            "constraints": {"forbiddenTargetCategories": ["trigger"]}
                        }
                    ],
                    "visible": True
                }
            ],
            "model": {"type": "bpmn:StartEvent", "entryPointId": True},
            "outputDefinition": {
